CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS access_keys (id BIGSERIAL PRIMARY KEY, key_hash TEXT UNIQUE NOT NULL, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, expires_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS coupons (id BIGSERIAL PRIMARY KEY, code_hash TEXT UNIQUE NOT NULL, days INTEGER NOT NULL CHECK(days > 0), max_uses INTEGER NOT NULL DEFAULT 1, used_count INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS voices (id TEXT PRIMARY KEY, name TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'bn', provider TEXT NOT NULL, provider_voice_id TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS generations (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), voice_id TEXT REFERENCES voices(id), text_chars INTEGER NOT NULL, status TEXT NOT NULL, audio_url TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS app_config (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS announcements (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, active BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, details JSONB, created_at TIMESTAMPTZ DEFAULT now());
